268.     fn should_retain_moduledef(&self, module_def_hir: hir::ModuleDef) -> bool {
269.         if self.options.selection.no_externs && self.is_extern(module_def_hir) {
270.             return false;
271.         }
272. 
273.         if !self.options.cfg_test && has_test_cfg(module_def_hir, self.db) {
274.             return false;
275.         }
276. 
277.         match module_def_hir {
278.             hir::ModuleDef::Module(module_hir) => self.should_retain_module(module_hir),
279.             hir::ModuleDef::Function(function_hir) => self.should_retain_function(function_hir),
280.             hir::ModuleDef::Adt(adt_hir) => self.should_retain_adt(adt_hir),
281.             hir::ModuleDef::Variant(variant_hir) => self.should_retain_variant(variant_hir),
282.             hir::ModuleDef::Const(const_hir) => self.should_retain_const(const_hir),
283.             hir::ModuleDef::Static(static_hir) => self.should_retain_static(static_hir),
284.             hir::ModuleDef::Trait(trait_hir) => self.should_retain_trait(trait_hir),
285.             hir::ModuleDef::TraitAlias(trait_alias_hir) => {
286.                 self.should_retain_trait_alias(trait_alias_hir)
287.             }
288.             hir::ModuleDef::TypeAlias(type_alias_hir) => {
289.                 self.should_retain_type_alias(type_alias_hir)
290.             }
291.             hir::ModuleDef::BuiltinType(builtin_type_hir) => {
