374.     fn is_extern(&self, module_def_hir: hir::ModuleDef) -> bool {
375.         let module = if let hir::ModuleDef::Module(module_hir) = module_def_hir {
376.             Some(module_hir)
377.         } else {
378.             module_def_hir.module(self.db)
379.         };
380. 
381.         let Some(import_krate) = module.map(|module| module.krate()) else {
382.             return true;
383.         };
384. 
385.         self.krate != import_krate
386.     }
