388.     fn nodes_reachable_from(
389.         graph: &Graph<Node, Edge>,
390.         start_node_idx: NodeIndex,
391.     ) -> HashSet<NodeIndex> {
392.         let mut reachability_walker = GraphWalker::new(petgraph::Direction::Outgoing);
393.         reachability_walker.walk_graph(graph, start_node_idx, |_edge, _node, _depth| true);
394.         reachability_walker.nodes_visited
395.     }
396. 
397.     fn nodes_within_max_depth_from<'b, I>(
398.         graph: &Graph<Node, Edge>,
399.         max_depth: usize,
400.         start_node_idxs: I,
401.     ) -> HashSet<NodeIndex>
402.     where
403.         I: 'b + IntoIterator<Item = &'b NodeIndex>,
404.     {
405.         let mut nodes_to_keep: HashSet<NodeIndex> = HashSet::default();
406. 
407.         // Walk graph, collecting visited nodes:
408.         for start_node_idx in start_node_idxs {
409.             // Walks from a node to its descendants in the graph (i.e. sub-items & dependencies):
410.             let mut descendants_walker = GraphWalker::new(petgraph::Direction::Outgoing);
411.             descendants_walker.walk_graph(graph, *start_node_idx, |_edge, _node, depth| {
412.                 depth <= max_depth
413.             });
414.             nodes_to_keep.extend(descendants_walker.nodes_visited);
415. 
416.             // Walks from a node to its ascendants in the graph (i.e. super-items & dependents):
417.             let mut ascendants_walker = GraphWalker::new(petgraph::Direction::Incoming);
418.             ascendants_walker.walk_graph(graph, *start_node_idx, |edge, _node, depth| {
419.                 (*edge == Edge::Owns) || (depth <= max_depth)
420.             });
421.             nodes_to_keep.extend(ascendants_walker.nodes_visited);
422.         }
423.         nodes_to_keep
424.     }
425. }
