437. struct VisibilityFilter {
438.     excluded_visibilities: HashSet<ExcludedVisibility>,
439. }
440. 
441. impl VisibilityFilter {
442.     fn build_from_options(options: &Options) -> Self {
443.         let mut hs = HashSet::new();
444.         if options.selection.no_private {
445.             hs.insert(ExcludedVisibility::Private);
