16. 
17. use super::orphan::Orphan;
18. 
19. #[derive(Debug)]
20. pub struct Scanner<'a> {
21.     db: &'a ide::RootDatabase,
22.     vfs: &'a vfs::Vfs,
23.     krate: hir::Crate,
24.     edition: ide::Edition,
25. }
26. 
27. impl<'a> Scanner<'a> {
28.     pub fn new(
29.         db: &'a ide::RootDatabase,
30.         vfs: &'a vfs::Vfs,
31.         krate: hir::Crate,
32.         edition: ide::Edition,
33.     ) -> Self {
34.         Self {
35.             db,
36.             vfs,
37.             krate,
38.             edition,
39.         }
40.     }
41. 
42.     pub fn scan(mut self) -> anyhow::Result<HashSet<Orphan>> {
43.         tracing::trace!("Scanning project ...");
44. 
45.         let orphans = self.process_crate(self.krate);
46. 
47.         Ok(orphans)
48.     }
49. 
50.     fn process_crate(&mut self, krate: hir::Crate) -> HashSet<Orphan> {
51.         let mut orphans = HashSet::new();
52.         let mut callback = |orphan| {
53.             orphans.insert(orphan);
54.         };
55. 
56.         let root_module = krate.root_module();
57.         self.process_module(root_module, &mut callback);
58. 
59.         orphans
60.     }
61. 
62.     fn process_module(&mut self, module_hir: hir::Module, callback: &mut dyn FnMut(Orphan)) {
63.         let Some(module_path) =
64.             analyzer::path(hir::ModuleDef::Module(module_hir), self.db, self.edition)
65.         else {
66.             return;
67.         };
68. 
69.         let file_path = analyzer::module_file(module_hir, self.db, self.vfs);
70. 
71.         let submodules: Vec<hir::Module> = module_hir
72.             .declarations(self.db)
73.             .into_iter()
74.             .filter_map(|module_def_hir| match module_def_hir {
75.                 hir::ModuleDef::Module(module_hir) => Some(module_hir),
76.                 _ => None,
77.             })
78.             .collect();
79. 
80.         let submodule_names: HashSet<String> = submodules
81.             .iter()
82.             .filter_map(|module_hir| {
83.                 analyzer::name(hir::ModuleDef::Module(*module_hir), self.db, self.edition)
84.             })
85.             .collect();
86. 
87.         if let Some(file_path) = file_path {
88.             for orphan in orphans_of_module(&module_path, &file_path, &submodule_names) {
89.                 callback(orphan);
90.             }
91.         }
92. 
93.         for module_hir in submodules {
94.             self.process_module(module_hir, callback);
95.         }
96.     }
97. }
98. 
99. pub(crate) fn orphans_of_module(
100.     module_path: &str,
101.     file_path: &Path,
102.     submodule_names: &HashSet<String>,
103. ) -> Vec<Orphan> {
104.     tracing::trace!("Searching for orphans of {module_path:?}");
105. 
106.     let dir_path_buf = match mod_dir(file_path) {
107.         Some(path_buf) => path_buf,
108.         None => {
109.             tracing::debug!("Could not obtain module directory path for {module_path:?}",);
110.             return vec![];
111.         }
112.     };
113.     let dir_path = dir_path_buf.as_path();
114. 
115.     if !dir_path.exists() {
116.         tracing::debug!("Module directory for {module_path:?} not found");
117.         return vec![];
118.     }
119. 
120.     let read_dir = match fs::read_dir(dir_path) {
121.         Ok(read_dir) => read_dir,
122.         Err(_) => {
123.             tracing::debug!("Module directory for {module_path:?} not readable");
124.             return vec![];
125.         }
126.     };
127. 
128.     possible_orphans_in(read_dir)
129.         .filter_map(|possible_orphan| {
130.             if submodule_names.contains(&possible_orphan.name) {
131.                 return None;
132.             }
133. 
134.             Some(Orphan {
135.                 name: possible_orphan.name,
136.                 file_path: possible_orphan.file_path,
137.                 parent_module_path: module_path.to_owned(),
138.                 parent_file_path: file_path.to_owned(),
139.             })
140.         })
141.         .collect()
142. }
143. 
144. fn mod_dir(file_path: &Path) -> Option<PathBuf> {
145.     let file_stem = file_path.file_stem().and_then(|os_str| os_str.to_str());
146.     let extension = file_path.extension().and_then(|os_str| os_str.to_str());
147. 
148.     match (file_stem, extension) {
149.         (Some("lib"), Some("rs")) | (Some("main"), Some("rs")) | (Some("mod"), Some("rs")) => {
150.             file_path.parent().map(|p| p.to_path_buf())
151.         }
152.         (Some(file_stem), Some("rs")) => file_path.parent().map(|p| p.join(file_stem)),
153.         _ => None,
154.     }
155. }
156. 
157. pub struct PossibleOrphan {
158.     pub name: String,
159.     pub file_path: PathBuf,
160. }
161. 
162. fn possible_orphans_in(read_dir: ReadDir) -> impl Iterator<Item = PossibleOrphan> {
163.     fn is_possible_identifier(name: &str) -> bool {
164.         name.chars().all(|c| c.is_alphanumeric())
165.     }
166. 
167.     read_dir.into_iter().filter_map(|dir_entry| {
168.         let entry_path = match dir_entry {
169.             Ok(dir_entry) => dir_entry.path(),
170.             Err(_) => {
171.                 // If we can't retrieve the entry, then skip over it:
172.                 return None;
173.             }
174.         };
175.         let file_stem = match entry_path.file_stem().and_then(|os_str| os_str.to_str()) {
176.             Some(name) => name,
177.             None => {
178.                 // A rust file should have a file-stem (aka file-name)
