195. pub fn select_package_and_target(
196.     project_workspace: &project_model::ProjectWorkspace,
197.     options: &ProjectOptions,
198. ) -> anyhow::Result<(project_model::PackageData, project_model::TargetData)> {
199.     let cargo_workspace = match project_workspace.kind {
200.         project_model::ProjectWorkspaceKind::Cargo { ref cargo, .. } => Ok(cargo),
201.         project_model::ProjectWorkspaceKind::Json { .. } => {
202.             Err(anyhow::anyhow!("Unexpected JSON workspace"))
203.         }
204.         project_model::ProjectWorkspaceKind::DetachedFile { .. } => {
205.             Err(anyhow::anyhow!("Unexpected detached files"))
206.         }
207.     }?;
208. 
209.     let package_idx = select_package(cargo_workspace, options)?;
210.     let package = cargo_workspace[package_idx].clone();
211.     tracing::debug!("Selected package: {:#?}", package.name);
212. 
213.     let target_idx = select_target(cargo_workspace, package_idx, options)?;
214.     let target = cargo_workspace[target_idx].clone();
215.     tracing::debug!("Selected target: {:#?}", target.name);
216. 
