220. pub fn select_package(
221.     workspace: &project_model::CargoWorkspace,
222.     options: &ProjectOptions,
223. ) -> anyhow::Result<project_model::Package> {
224.     let packages: Vec<_> = workspace
225.         .packages()
226.         .filter(|idx| workspace[*idx].is_member)
227.         .collect();
228. 
229.     let package_count = packages.len();
230. 
231.     // If project contains no packages, bail out:
232. 
233.     if package_count < 1 {
234.         anyhow::bail!("no packages found");
235.     }
236. 
237.     // If no (or a non-existent) package was provided via options bail out:
238. 
239.     let package_list_items: Vec<_> = packages
240.         .iter()
241.         .map(|package_idx| {
242.             let package = &workspace[*package_idx];
243.             format!("- {}", package.name)
244.         })
245.         .collect();
246. 
247.     let package_list = package_list_items.join("\n");
248. 
249.     // If project contains multiple packages, select the one provided via options:
250. 
251.     if let Some(package_name) = &options.package {
252.         let package_idx = packages.into_iter().find(|package_idx| {
253.             let package = &workspace[*package_idx];
254.             package.name == *package_name
255.         });
256. 
257.         return package_idx.ok_or_else(|| {
258.             anyhow::anyhow!(
259.                 indoc::indoc! {
260.                     "No package found with name {:?}.
261. 
262.                         Packages present in workspace:
263.                         {}
264.                         "
265.                 },
266.                 package_name,
267.                 package_list,
268.             )
269.         });
270.     }
271. 
272.     // If project contains a single packages, just pick it:
273. 
274.     if package_count == 1 {
275.         return Ok(packages[0]);
276.     }
277. 
278.     Err(anyhow::anyhow!(
279.         indoc::indoc! {
280.             "Multiple packages present in workspace,
281.                 please explicitly select one via --package flag.
282. 
283.                 Packages present in workspace:
284.                 {}
285.                 "
286.         },
287.         package_list
288.     ))
289. }
