291. pub fn select_target(
292.     workspace: &project_model::CargoWorkspace,
293.     package_idx: project_model::Package,
294.     options: &ProjectOptions,
295. ) -> anyhow::Result<project_model::Target> {
296.     let package = &workspace[package_idx];
297. 
298.     // Retrieve list of indices for bin/lib targets:
299. 
300.     let targets: Vec<_> = package
301.         .targets
302.         .iter()
303.         .cloned()
304.         .filter(|target_idx| {
305.             let target = &workspace[*target_idx];
306.             match target.kind {
307.                 project_model::TargetKind::Bin => true,
308.                 project_model::TargetKind::Lib { .. } => true,
309.                 project_model::TargetKind::Example => false,
310.                 project_model::TargetKind::Test => false,
311.                 project_model::TargetKind::Bench => false,
312.                 project_model::TargetKind::Other => false,
313.                 project_model::TargetKind::BuildScript => false,
314.             }
315.         })
316.         .collect();
317. 
318.     let target_count = targets.len();
319. 
320.     // If package contains no targets, bail out:
321. 
322.     if target_count < 1 {
323.         anyhow::bail!("no targets found");
324.     }
325. 
326.     // If no (or a non-existent) target was provided via options bail out:
327. 
328.     let target_list_items: Vec<_> = targets
329.         .iter()
330.         .map(|target_idx| {
331.             let target = &workspace[*target_idx];
332.             match target.kind {
333.                 project_model::TargetKind::Bin => {
334.                     format!("- {} (--bin {})", target.name, target.name)
335.                 }
336.                 project_model::TargetKind::Lib { .. } => format!("- {} (--lib)", target.name),
337.                 project_model::TargetKind::Example => unreachable!(),
338.                 project_model::TargetKind::Test => unreachable!(),
339.                 project_model::TargetKind::Bench => unreachable!(),
340.                 project_model::TargetKind::Other => unreachable!(),
341.                 project_model::TargetKind::BuildScript => unreachable!(),
342.             }
343.         })
344.         .collect();
345. 
346.     let target_list = target_list_items.join("\n");
347. 
348.     // If package contains multiple targets, select the one provided via options:
349. 
350.     if options.lib {
351.         let target = targets.into_iter().find(|target_idx| {
352.             let target = &workspace[*target_idx];
353.             matches!(target.kind, project_model::TargetKind::Lib { .. })
354.         });
355. 
356.         return target.ok_or_else(|| {
357.             anyhow::anyhow!(
358.                 indoc::indoc! {
359.                     "No library target found.
360. 
361.                         Targets present in package:
362.                         {}
363.                         "
364.                 },
365.                 target_list,
366.             )
367.         });
368.     }
369. 
370.     if let Some(bin_name) = &options.bin {
371.         let target = targets.into_iter().find(|target_idx| {
372.             let target = &workspace[*target_idx];
373.             (target.kind == project_model::TargetKind::Bin) && (target.name == bin_name[..])
374.         });
375. 
376.         return target.ok_or_else(|| {
377.             anyhow::anyhow!(
378.                 indoc::indoc! {
379.                     "No binary target found with name {:?}.
380. 
381.                         Targets present in package:
382.                         {}
383.                         "
384.                 },
385.                 bin_name,
386.                 target_list,
387.             )
388.         });
389.     }
390. 
391.     // If project contains a single target, just pick it:
392. 
393.     if target_count == 1 {
394.         return Ok(targets[0]);
395.     }
396. 
397.     Err(anyhow::anyhow!(
398.         indoc::indoc! {
399.             "Multiple targets present in package,
400.                 please explicitly select one via --lib or --bin flag.
401. 
402.                 Targets present in package:
403.                 {}
404.                 "
405.         },
406.         target_list
407.     ))
408. }
