674. 
675.     let test_key = hir::Symbol::intern("test");
676.     let cfg_exprs: Vec<_> = attrs.cfgs().collect();
677. 
678.     cfg_exprs.into_iter().any(|cfg_expr| {
679.         cfg_expr
680.             .fold(&|cfg| {
681.                 use ra_ap_cfg::CfgAtom;
682.                 match cfg {
