697. pub fn cfgs(hir: hir::ModuleDef, db: &ide::RootDatabase) -> Vec<cfg::CfgExpr> {
698.     let cfg = match cfg(hir, db) {
699.         Some(cfg) => cfg,
700.         None => return vec![],
701.     };
702. 
703.     match cfg {
704.         cfg::CfgExpr::Invalid => vec![],
705.         cfg @ cfg::CfgExpr::Atom(_) => vec![cfg],
706.         cfg::CfgExpr::All(cfgs) => cfgs.to_vec(),
707.         cfg @ cfg::CfgExpr::Any(_) => vec![cfg],
708.         cfg @ cfg::CfgExpr::Not(_) => vec![cfg],
