716.         hir::ModuleDef::Adt(adt) => adt.attrs(db).cfg(),
717.         hir::ModuleDef::Variant(r#variant) => r#variant.attrs(db).cfg(),
718.         hir::ModuleDef::Const(r#const) => r#const.attrs(db).cfg(),
719.         hir::ModuleDef::Static(r#static) => r#static.attrs(db).cfg(),
720.         hir::ModuleDef::Trait(r#trait) => r#trait.attrs(db).cfg(),
721.         hir::ModuleDef::TraitAlias(trait_type) => trait_type.attrs(db).cfg(),
722.         hir::ModuleDef::TypeAlias(type_alias) => type_alias.attrs(db).cfg(),
723.         hir::ModuleDef::BuiltinType(_builtin_type) => None,
