748. pub fn module_file(module: hir::Module, db: &ide::RootDatabase, vfs: &vfs::Vfs) -> Option<PathBuf> {
749.     let module_source = module.definition_source(db);
750.     let is_file_module: bool = match &module_source.value {
751.         hir::ModuleSource::SourceFile(_) => true,
752.         hir::ModuleSource::Module(_) => false,
753.         hir::ModuleSource::BlockExpr(_) => false,
754.     };
755. 
756.     if !is_file_module {
757.         return None;
758.     }
759. 
760.     let file_id = module_source.file_id.original_file(db);
761.     let vfs_path = vfs.file_path(file_id.file_id(db));
762.     let abs_path = vfs_path.as_path().expect("Could not convert to path");
763. 
764.     let path: &Path = abs_path.as_ref();
765. 
766.     let file_extension = path.extension().and_then(|ext| ext.to_str());
767. 
768.     if file_extension != Some("rs") {
769.         return None;
770.     }
771. 
772.     Some(path.to_owned())
773. }
