4. 
5. use std::collections::{HashMap, HashSet};
6. 
7. use ra_ap_hir::{self as hir};
8. use ra_ap_hir_def::{self as hir_def};
9. use ra_ap_hir_ty::{self as hir_ty, TyExt as _, db::HirDatabase as _, from_assoc_type_id};
10. use ra_ap_ide::{self as ide, Edition};
11. 
12. use petgraph::graph::{EdgeIndex, NodeIndex};
13. 
14. use crate::{
15.     analyzer,
16.     graph::{Edge, Graph, Node, Relationship},
17.     item::Item,
18. };
19. 
20. #[allow(unused)]
21. #[derive(Debug, Hash, Eq, PartialEq)]
22. struct Dependency {
23.     source_idx: NodeIndex,
24.     target_hir: hir::ModuleDef,
25. }
26. 
27. #[derive(Debug)]
28. pub struct GraphBuilder<'a> {
29.     db: &'a ide::RootDatabase,
30.     edition: ide::Edition,
31.     krate: hir::Crate,
32.     graph: Graph<Node, Edge>,
33.     nodes: HashMap<hir::ModuleDef, NodeIndex>,
34.     edges: HashMap<(NodeIndex, Relationship, NodeIndex), EdgeIndex>,
35. }
36. 
37. impl<'a> GraphBuilder<'a> {
38.     pub fn new(db: &'a ide::RootDatabase, edition: ide::Edition, krate: hir::Crate) -> Self {
39.         let graph = Graph::default();
40.         let nodes = HashMap::default();
41.         let edges = HashMap::default();
42. 
43.         Self {
44.             db,
45.             edition,
46.             krate,
47.             graph,
48.             nodes,
49.             edges,
50.         }
51.     }
52. 
53.     pub fn build(mut self) -> anyhow::Result<(Graph<Node, Edge>, NodeIndex)> {
54.         let _span = tracing::trace_span!("Scanning project...").entered();
55. 
56.         let node_idx = self
57.             .process_crate(self.krate)
58.             .expect("graph node for crate root module");
59. 
60.         Ok((self.graph, node_idx))
61.     }
62. 
63.     fn process_crate(&mut self, crate_hir: hir::Crate) -> Option<NodeIndex> {
64.         let _span = tracing::trace_span!(
65.             "crate",
66.             crate = crate_hir
67.                 .display_name(self.db)
68.                 .map(|name| name.to_string())
69.                 .unwrap_or_else(|| "<ANONYMOUS>".to_owned())
70.         )
71.         .entered();
72. 
73.         let module = crate_hir.root_module();
74. 
75.         let node_idx = self.process_moduledef(module.into());
76. 
77.         for impl_hir in hir::Impl::all_in_crate(self.db, crate_hir) {
78.             let impl_ty = impl_hir.self_ty(self.db);
79. 
80.             let impl_ty_hir = if let Some(adt_hir) = impl_ty.as_adt() {
81.                 Some(hir::ModuleDef::Adt(adt_hir))
82.             } else {
83.                 impl_ty.as_builtin().map(hir::ModuleDef::BuiltinType)
84.             };
85. 
86.             let Some(impl_ty_hir) = impl_ty_hir else {
87.                 continue;
88.             };
89. 
90.             let Some(&impl_ty_idx) = self.nodes.get(&impl_ty_hir) else {
91.                 let ty_path = analyzer::display_path(impl_ty_hir, self.db, self.edition);
92.                 tracing::debug!("Could not find node for type {ty_path:?}, skipping impl.");
93.                 continue;
94.             };
95. 
96.             for impl_item_idx in self.process_impl(impl_hir) {
97.                 self.add_edge(impl_ty_idx, impl_item_idx, Edge::Owns);
98.             }
99.         }
100. 
101.         node_idx
102.     }
103. 
104.     fn process_impl(&mut self, impl_hir: hir::Impl) -> Vec<NodeIndex> {
105.         let _span = tracing::trace_span!("impl").entered();
106. 
107.         impl_hir
108.             .items(self.db)
109.             .into_iter()
110.             .filter_map(|item| {
111.                 let mut dependencies: HashSet<_> = HashSet::default();
112. 
113.                 let mut push_dependencies = |module_def_hir| {
114.                     dependencies.insert(module_def_hir);
115.                 };
116. 
117.                 let item_idx = match item {
118.                     hir::AssocItem::Function(function_hir) => {
119.                         self.process_function(function_hir, &mut push_dependencies)
120.                     }
121.                     hir::AssocItem::Const(const_hir) => {
122.                         self.process_const(const_hir, &mut push_dependencies)
123.                     }
124.                     hir::AssocItem::TypeAlias(type_alias_hir) => {
125.                         self.process_type_alias(type_alias_hir, &mut push_dependencies)
126.                     }
127.                 };
128. 
129.                 if let Some(item_idx) = item_idx {
130.                     self.add_dependencies(item_idx, dependencies.clone());
131.                 }
132. 
133.                 item_idx
134.             })
135.             .collect()
136.     }
137. 
138.     fn process_moduledef(&mut self, module_def_hir: hir::ModuleDef) -> Option<NodeIndex> {
139.         let mut dependencies: HashSet<_> = HashSet::default();
140. 
141.         let mut push_dependencies = |module_def_hir| {
142.             dependencies.insert(module_def_hir);
143.         };
144. 
145.         let node_idx = match module_def_hir {
146.             hir::ModuleDef::Module(module_hir) => {
147.                 self.process_module(module_hir, &mut push_dependencies)
148.             }
149.             hir::ModuleDef::Function(function_hir) => {
150.                 self.process_function(function_hir, &mut push_dependencies)
151.             }
152.             hir::ModuleDef::Adt(adt_hir) => self.process_adt(adt_hir, &mut push_dependencies),
153.             hir::ModuleDef::Variant(variant_hir) => {
154.                 self.process_variant(variant_hir, &mut push_dependencies)
155.             }
156.             hir::ModuleDef::Const(const_hir) => {
157.                 self.process_const(const_hir, &mut push_dependencies)
158.             }
159.             hir::ModuleDef::Static(static_hir) => {
160.                 self.process_static(static_hir, &mut push_dependencies)
161.             }
162.             hir::ModuleDef::Trait(trait_hir) => {
163.                 self.process_trait(trait_hir, &mut push_dependencies)
164.             }
165.             hir::ModuleDef::TraitAlias(trait_alias_hir) => {
166.                 self.process_trait_alias(trait_alias_hir, &mut push_dependencies)
167.             }
168.             hir::ModuleDef::TypeAlias(type_alias_hir) => {
169.                 self.process_type_alias(type_alias_hir, &mut push_dependencies)
170.             }
171.             hir::ModuleDef::BuiltinType(builtin_type_hir) => {
172.                 self.process_builtin_type(builtin_type_hir, &mut push_dependencies)
173.             }
174.             hir::ModuleDef::Macro(macro_hir) => {
175.                 self.process_macro(macro_hir, &mut push_dependencies)
176.             }
177.         };
178. 
179.         if let Some(node_idx) = node_idx.as_ref() {
180.             self.add_dependencies(*node_idx, dependencies.clone());
181.         }
182. 
183.         node_idx
184.     }
185. 
186.     fn process_module(
187.         &mut self,
188.         module_hir: hir::Module,
189.         dependencies_callback: &mut dyn FnMut(hir::ModuleDef),
190.     ) -> Option<NodeIndex> {
191.         let _span = tracing::trace_span!(
192.             "module",
193.             module = module_hir
194.                 .name(self.db)
195.                 .map(|name| name.display(self.db, Edition::CURRENT).to_string())
196.                 .unwrap_or_else(|| "<ROOT>".to_owned())
197.         )
198.         .entered();
199. 
200.         let node_idx = self.add_node_if_necessary(module_hir.into());
201. 
202.         if let Some(node_idx) = node_idx {
203.             // Process sub-items:
204.             for declaration in module_hir.declarations(self.db) {
205.                 let Some(declaration_idx) = self.process_moduledef(declaration) else {
206.                     continue;
207.                 };
208. 
209.                 self.add_edge(node_idx, declaration_idx, Edge::Owns);
210.             }
211.         }
212. 
213.         for (_name, scope_hir) in module_hir.scope(self.db, None) {
214.             let hir::ScopeDef::ModuleDef(scope_module_hir) = scope_hir else {
215.                 // Skip everything but module-defs:
216.                 continue;
217.             };
218. 
219.             // Check if definition is a child of `module`:
220.             if scope_module_hir.module(self.db) == Some(module_hir) {
221.                 // Is a child, omit it:
222.                 continue;
223.             }
224. 
225.             dependencies_callback(scope_module_hir);
226.         }
227. 
228.         node_idx
229.     }
230. 
231.     fn process_function(
232.         &mut self,
233.         function_hir: hir::Function,
234.         dependencies_callback: &mut dyn FnMut(hir::ModuleDef),
235.     ) -> Option<NodeIndex> {
236.         let _span = tracing::trace_span!(
237.             "function",
238.             function = function_hir
239.                 .name(self.db)
240.                 .display(self.db, Edition::CURRENT)
241.                 .to_string()
242.         )
243.         .entered();
244. 
245.         let node_idx = self.add_node_if_necessary(hir::ModuleDef::Function(function_hir))?;
246. 
247.         for param in function_hir.params_without_self(self.db) {
248.             Self::walk_and_push_type(
249.                 param.ty().strip_references(),
250.                 self.db,
251.                 self.edition,
252.                 dependencies_callback,
253.             );
254.         }
255. 
256.         for param in function_hir.assoc_fn_params(self.db) {
257.             Self::walk_and_push_type(
258.                 param.ty().strip_references(),
259.                 self.db,
260.                 self.edition,
261.                 dependencies_callback,
262.             );
263.         }
264. 
265.         let return_type = function_hir.ret_type(self.db);
266.         Self::walk_and_push_type(
267.             return_type.strip_references(),
268.             self.db,
269.             self.edition,
270.             dependencies_callback,
271.         );
272. 
273.         let def_with_body = hir::DefWithBody::from(function_hir);
274.         let def_with_body_id: hir_def::DefWithBodyId = def_with_body.into();
275.         let inference_result = self.db.infer(def_with_body_id);
276. 
277.         for (_id, ty) in inference_result.type_of_binding.iter() {
278.             Self::walk_and_push_ty(ty.clone(), self.db, self.edition, dependencies_callback);
279.         }
280. 
281.         for (_id, ty) in inference_result.type_of_expr.iter() {
282.             Self::walk_and_push_ty(ty.clone(), self.db, self.edition, dependencies_callback);
283.         }
284. 
285.         for (_id, ty) in inference_result.type_of_for_iterator.iter() {
286.             Self::walk_and_push_ty(ty.clone(), self.db, self.edition, dependencies_callback);
287.         }
288. 
289.         for (_id, ty) in inference_result.type_of_pat.iter() {
290.             Self::walk_and_push_ty(ty.clone(), self.db, self.edition, dependencies_callback);
291.         }
292. 
293.         for (_id, ty) in inference_result.type_of_rpit.iter() {
294.             Self::walk_and_push_ty(ty.clone(), self.db, self.edition, dependencies_callback);
295.         }
296. 
297.         Some(node_idx)
298.     }
299. 
300.     fn process_adt(
301.         &mut self,
302.         adt_hir: hir::Adt,
303.         dependencies_callback: &mut dyn FnMut(hir::ModuleDef),
304.     ) -> Option<NodeIndex> {
305.         match adt_hir {
306.             hir::Adt::Struct(struct_hir) => self.process_struct(struct_hir, dependencies_callback),
307.             hir::Adt::Enum(enum_hir) => self.process_enum(enum_hir, dependencies_callback),
308.             hir::Adt::Union(union_hir) => self.process_union(union_hir, dependencies_callback),
309.         }
310.     }
311. 
312.     fn process_struct(
313.         &mut self,
314.         struct_hir: hir::Struct,
315.         dependencies_callback: &mut dyn FnMut(hir::ModuleDef),
316.     ) -> Option<NodeIndex> {
317.         let _span = tracing::trace_span!("struct",
318.             struct = struct_hir
319.                 .name(self.db)
320.                 .display(self.db, Edition::CURRENT)
321.                 .to_string())
322.         .entered();
323. 
324.         let node_idx =
325.             self.add_node_if_necessary(hir::ModuleDef::Adt(hir::Adt::Struct(struct_hir)));
326. 
327.         for field_hir in struct_hir.fields(self.db) {
328.             Self::walk_and_push_type(
329.                 field_hir.ty(self.db).strip_references(),
330.                 self.db,
331.                 self.edition,
332.                 dependencies_callback,
333.             );
334.         }
335. 
336.         node_idx
337.     }
