343.     ) -> Option<NodeIndex> {
344.         let _span = tracing::trace_span!("enum",
345.             enum = enum_hir
346.                 .name(self.db)
347.                 .display(self.db, Edition::CURRENT)
348.                 .to_string())
349.         .entered();
350. 
351.         let node_idx = self.add_node_if_necessary(hir::ModuleDef::Adt(hir::Adt::Enum(enum_hir)));
352. 
353.         for variant_hir in enum_hir.variants(self.db) {
354.             for field_hir in variant_hir.fields(self.db) {
