368.         &mut self,
369.         union_hir: hir::Union,
370.         dependencies_callback: &mut dyn FnMut(hir::ModuleDef),
371.     ) -> Option<NodeIndex> {
372.         let _span = tracing::trace_span!(
373.             "union",
374.             union = union_hir
375.                 .name(self.db)
376.                 .display(self.db, Edition::CURRENT)
377.                 .to_string()
378.         )
