125. pub fn from_placeholder_idx(db: &dyn HirDatabase, idx: PlaceholderIndex) -> TypeOrConstParamId {
126.     assert_eq!(idx.ui, chalk_ir::UniverseIndex::ROOT);
127.     // SAFETY: We cannot really encapsulate this unfortunately, so just hope this is sound.
128.     let interned_id = FromId::from_id(unsafe { Id::from_u32(idx.idx.try_into().unwrap()) });
129.     db.lookup_intern_type_or_const_param_id(interned_id)
